let investmentCategory:InvestmentCategory='space';let reviewing:Purchase|undefined;
let celebration:StarCelebration|undefined;
const noAds=new LifetimeNoAds(),reviewAccess=new ReviewAccess(),diamondStore=new DiamondStore();await Promise.all([noAds.loadCached(),reviewAccess.loadCached(),diamondStore.loadCached()]);
const premiumOwned=()=>noAds.owned||reviewAccess.state.active;
const premiumActivatedAt=()=>Math.min(...[noAds.owned?noAds.activatedAt:Infinity,reviewAccess.state.active?reviewAccess.state.activatedAt:Infinity]);
const playGames=new CafePlayGames();
const adTiming=new InterstitialTiming();let adBreakBusy=false,nextPreloadAt=0,bonusProcessing=false,adBackground=false,diamondsProcessing=false;
const loaded=load(localStorage);const game=new Simulation(loaded.save);let offline=game.offline(Date.now(),premiumOwned(),premiumActivatedAt());setLocale(game.s.settings.locale);document.title='Mola · '+t('Kendi kahve hikâyen');const audio=new CafeAudio(),ads=new RewardedAds();let pressedGuideId:string|undefined;let displayedGuideId='',guideShownAt=0;let guideTapped=false,allTools=false,guideMarkup='',started=false,hidden=false,modal='',lastFocus:HTMLElement|null=null,toastTimer=0,saveTimer=0,uiTimer=0;
